    local authorizedSet = {}
    for _, digest in ipairs(AUTHORIZED_KEY_DIGESTS) do
        authorizedSet[digest] = true
    end

    local function normalize_key(value)
        return string.upper(string.gsub(tostring(value or ""), "%s+", ""))
    end

    local function secure_digest(value)
        value = tostring(value or "")
        local left = 2166136261
        local right = 5381

        for index = 1, #value do
            local byte = string.byte(value, index)
            left = (left * 131 + byte * 7877) % 2147483647
            right = (right * 137 + byte * 104729) % 2147483647
        end

        return string.format("%08X%08X", left, right)
    end

    local function checksum_block(blockOne, blockTwo, blockThree)
        local data = KEY_SECRET .. "|" .. blockOne .. "|" .. blockTwo .. "|" .. blockThree
        local hash = 5381

        for index = 1, #data do
            hash = (hash * 131 + string.byte(data, index) * 7877) % 2147483647
        end

        local output = ""
        for _ = 1, 5 do
            output ..= string.sub(KEY_CHARS, (hash % #KEY_CHARS) + 1, (hash % #KEY_CHARS) + 1)
            hash = math.floor(hash / #KEY_CHARS)
        end

        return output
    end

    local function inspect_paid_key(rawKey)
        local key = normalize_key(rawKey)
        local prefix, one, two, three, four = string.match(
            key,
            "^ENRIQUE%-PAID%-(.....)%-(.....)%-(.....)%-(.....)$"
        )

        local function validBlock(block)
            return type(block) == "string" and #block == 5 and string.match(block, "^[%u%d]+$") ~= nil
        end

        if not validBlock(one) or not validBlock(two) or not validBlock(three) or not validBlock(four) then
            return false, nil
        end

        if four ~= checksum_block(one, two, three) then
            return false, nil
        end

        local digest = secure_digest(key)
        if not authorizedSet[digest] then
            return false, nil
        end

        return true, digest
    end

    local function ensureFolder()
        if makefolder then pcall(makefolder, KEY_FOLDER) end
    end

    local function readJson(path)
        if not readfile or not isfile or not isfile(path) then return nil end
        local ok, data = pcall(function()
            return HttpService:JSONDecode(readfile(path))
        end)
        return ok and data or nil
    end

    local function writeJson(path, data)
        if not writefile then return false end
        ensureFolder()
        return pcall(function()
            writefile(path, HttpService:JSONEncode(data))
        end)
    end

    local function executorName()
        local ok, name = pcall(function()
            return identifyexecutor and identifyexecutor() or "Unknown Executor"
        end)
        return ok and tostring(name) or "Unknown Executor"
    end

    local function hardwareFingerprintSource()
        local candidates = {
            function() return gethwid and gethwid() end,
            function() return get_executor_id and get_executor_id() end,
            function() return syn and syn.hwid and syn.hwid() end,
        }

        for _, getter in ipairs(candidates) do
            local ok, value = pcall(getter)
            if ok and type(value) == "string" and #value > 5 then
                return value
            end
        end

        local path = KEY_FOLDER .. "/" .. DEVICE_FILE
        ensureFolder()
        if readfile and isfile and isfile(path) then
            local ok, saved = pcall(readfile, path)
            if ok and type(saved) == "string" and #saved >= 16 then
                return saved
            end
        end

        local generated = tostring(HttpService:GenerateGUID(false)) .. "|" .. tostring(math.random(100000, 999999))
        if writefile then pcall(writefile, path, generated) end
        return generated
    end

    local DEVICE_FINGERPRINT = secure_digest("ENRIQUE-DEVICE|" .. hardwareFingerprintSource())

    local function readBindings()
        local bindings = readJson(KEY_FOLDER .. "/" .. BINDING_FILE)
        return type(bindings) == "table" and bindings or {}
    end

    local function writeBindings(bindings)
        return writeJson(KEY_FOLDER .. "/" .. BINDING_FILE, bindings)
    end

    local function httpRequest(parameters)
        if syn and syn.request then
            return syn.request(parameters)
        elseif http and http.request then
            return http.request(parameters)
        elseif http_request then
            return http_request(parameters)
        elseif request then
            return request(parameters)
        end
        return nil, "NO_HTTP"
    end

    local function remoteValidate(key, digest)
        if KEY_SYNC_URL == "" then
            return nil, nil
        end

        local ok, response = pcall(httpRequest, {
            Url = KEY_SYNC_URL,
            Method = "POST",
            Headers = {["Content-Type"] = "application/json"},
            Body = HttpService:JSONEncode({
                action = "activate",
                key = key,
                licenseDigest = digest,
                fingerprint = DEVICE_FINGERPRINT,
                executor = executorName(),
            }),
        })

        if not ok or not response then
            return false, "LICENSE SERVER UNREACHABLE"
        end

        local body = response.Body or response.body or ""
        local decoded, data = pcall(function()
            return HttpService:JSONDecode(body)
        end)

        if not decoded or type(data) ~= "table" then
            return false, "LICENSE SERVER INVALID RESPONSE"
        end

        if data.allowed == false or data.valid == false then
            return false, tostring(data.message or "KEY ALREADY BOUND"), data.action == "kick"
        end

        if data.allowed == true or data.valid == true then
            return true, tostring(data.message or "AUTHORIZED"), false
        end

        return false, "LICENSE SERVER REJECTED KEY"
    end

    local function read_saved_session()
        local session = readJson(KEY_FOLDER .. "/" .. KEY_FILE)
        if type(session) ~= "table" or session.version ~= 2 then return nil end

        local valid, digest = inspect_paid_key(session.key)
        if not valid or session.fingerprint ~= DEVICE_FINGERPRINT then return nil end

        local expiry = tonumber(session.expires)
        if expiry ~= 0 and expiry ~= nil and os.time() >= expiry then return nil end

        local bindings = readBindings()
        local binding = bindings[digest]
        if binding and binding.fingerprint ~= DEVICE_FINGERPRINT then return nil end

        return session.key, expiry or 0
    end

