    local function saveSession(key, digest)
        local bindings = readBindings()
        bindings[secure_digest(key)] = {
            fingerprint = DEVICE_FINGERPRINT,
            executor = executorName(),
            boundAt = os.time(),
        }
        writeBindings(bindings)

        writeJson(KEY_FOLDER .. "/" .. KEY_FILE, {
            version = 2,
            key = key,
            digest = digest,
            fingerprint = DEVICE_FINGERPRINT,
            expires = 0,
            boundAt = os.time(),
        })
    end

    local function closeGate(tier)
        getgenv().ENRIQUE_PaidAuthenticated = true
        getgenv().ENRIQUE_KeyTier = tier or "Paid"
        getgenv().ENRIQUE_KeyExpires = 0

        tween(card, 0.24, {GroupTransparency = 1})
        tween(scrim, 0.26, {BackgroundTransparency = 1})
        task.delay(0.28, function()
            screenGui:Destroy()
        end)
    end

    local busy = false
    local function tryUnlock()
        if busy then return end
        local key = normalize_key(keyBox.Text)

        if #key < 10 then
            setStatus("Paste a private ENRIQUE Paid key.", Color3.fromRGB(206, 45, 76))
            tween(inputStroke, 0.08, {Thickness = 3}, Enum.EasingStyle.Linear)
            task.delay(0.14, function()
                tween(inputStroke, 0.20, {Thickness = 1}, Enum.EasingStyle.Linear)
            end)
            return
        end

        busy = true
        unlockButton.Text = "CHECKING..."
        unlockButton.BackgroundColor3 = Color3.fromRGB(164, 22, 50)
        task.wait(0.14)

        local valid, digest = inspect_paid_key(key)
        if not valid then
            busy = false
            unlockButton.Text = "ACTIVATE"
            unlockButton.BackgroundColor3 = Color3.fromRGB(224, 31, 64)
            setStatus("INVALID PRIVATE KEY", Color3.fromRGB(206, 45, 76))
            return
        end

        local bindings = readBindings()
        local binding = bindings[digest]
        if binding and binding.fingerprint ~= DEVICE_FINGERPRINT then
            busy = false
            unlockButton.Text = "LOCKED"
            unlockButton.BackgroundColor3 = Color3.fromRGB(80, 72, 84)
            setStatus("KEY IS ALREADY BOUND TO ANOTHER DEVICE", Color3.fromRGB(206, 45, 76))
            return
        end

        local allowed, message, shouldKick = remoteValidate(key, digest)
        if allowed == false then
            busy = false
            unlockButton.Text = "BLOCKED"
            unlockButton.BackgroundColor3 = Color3.fromRGB(80, 72, 84)
            setStatus(tostring(message), Color3.fromRGB(206, 45, 76))
            if shouldKick then
                task.delay(0.8, function()
                    LocalPlayer:Kick("[ENRIQUE] This key was activated on another device.")
                end)
            end
            return
        end

        saveSession(key, digest)
        setStatus("AUTHORIZED · PERMANENT DEVICE BINDING", Color3.fromRGB(21, 152, 92))
        unlockButton.Text = "AUTHORIZED"
        task.wait(0.22)
        busy = false
        closeGate("Paid")
    end

