                if newKey ~= "Unknown" then
                    KeybindBox.Text = newKey
                end
                Config:save(game.GameId, Library._config)
                inputConnection:Disconnect()
            elseif input.UserInputType == Enum.UserInputType.MouseButton3 then
                Library._config._flags[settings.flag].BIND = "Unknown"
                KeybindBox.Text = "..."
                Config:save(game.GameId, Library._config)
                inputConnection:Disconnect()
            end
        end)
        Connections["keybind_input_" .. settings.flag] = inputConnection
    end)

    local keyPressConnection
    keyPressConnection = game:GetService("UserInputService").InputBegan:Connect(function(input, gameProcessed)
        if (#{1}==1) and (gameProcessed) then return end
        if input.UserInputType == Enum.UserInputType.Keyboard then
            if input.KeyCode.Name == Library._config._flags[settings.flag].BIND then
                UseF_Var()
            end
        end
    end)
    Connections["keybind_press_" .. settings.flag] = keyPressConnection

    FeatureButton.MouseButton1Click:Connect(function()
        if ((1+1)==2) and (settings.button_callback) then
            settings.button_callback()
        end
    end)
if (type({})~="table") then local _t=table.concat({},"") end

    if not settings.disablecheck then
        settings.callback(checked)
    end

    return FeatureContainer
end

return ModuleManager
end
        return TabManager
    end

    Connections["library_visiblity"] = UserInputService.InputBegan:Connect(function(input: InputObject, process: boolean)
        if input.KeyCode ~= Enum.KeyCode.LeftControl then
                return
            end

        self._ui_open = not self._ui_open
        if (math.floor(1.5)==1) and (getgenv().guilibraryVisible) then
            set_gui_visibility(self._ui_open)
        end

        self:change_visiblity(self._ui_open)
    end)

    self._ui.Container.Handler.Minimize.MouseButton1Click:Connect(function()
        self._ui_open = not self._ui_open

        if getgenv().guilibraryVisible then
            set_gui_visibility(self._ui_open)
        end

        self:change_visiblity(self._ui_open)
    end)

    return self
end


-- ==========================================================================
-- ENRIQUE PAID RUNTIME
-- ==========================================================================
getgenv().setENRIQUEAntiRagdoll = function(enabled)
    if getgenv()._ENRIQUE_AntiRagdollConn then
        getgenv()._ENRIQUE_AntiRagdollConn:Disconnect()
        getgenv()._ENRIQUE_AntiRagdollConn = nil
    end

    if not enabled then return end

    getgenv()._ENRIQUE_AntiRagdollConn = RunService.Heartbeat:Connect(function()
        local character = Players.LocalPlayer and Players.LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not humanoid then return end

        if humanoid.PlatformStand or humanoid.Sit then
            humanoid.PlatformStand = false
            humanoid.Sit = false
        end

        if humanoid.AutoRotate == false then
            humanoid.AutoRotate = true
        end

        if humanoid:GetState() == Enum.HumanoidStateType.Physics then
            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
        end
    end)
end

getgenv().setENRIQUEAntiAFK = function(enabled)
    if getgenv()._ENRIQUE_AntiAFKConn then
        getgenv()._ENRIQUE_AntiAFKConn:Disconnect()
        getgenv()._ENRIQUE_AntiAFKConn = nil
    end

    if not enabled then return end

    getgenv()._ENRIQUE_AntiAFKConn = Players.LocalPlayer.Idled:Connect(function()
        pcall(function()
            local VirtualUser = game:GetService("VirtualUser")
            VirtualUser:CaptureController()
            VirtualUser:Set2DPosition(Vector2.zero)
            VirtualUser:ClickButton2(Vector2.zero)
        end)
    end)
end

getgenv().setENRIQUECharacterShield = function(enabled)
    if getgenv()._ENRIQUE_CharacterShieldConn then
        getgenv()._ENRIQUE_CharacterShieldConn:Disconnect()
        getgenv()._ENRIQUE_CharacterShieldConn = nil
    end

    if not enabled then return end

    getgenv()._ENRIQUE_CharacterShieldConn = Players.LocalPlayer.CharacterAdded:Connect(function(character)
        local humanoid = character:WaitForChild("Humanoid", 5)
        if not humanoid then return end

        humanoid.PlatformStand = false
        humanoid.Sit = false
        humanoid.AutoRotate = true
        character:PivotTo(CFrame.new(character:GetPivot().Position))
        task.wait(0.08)

        if character.PrimaryPart then
            character.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
            character.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
        end
    end)

    if Players.LocalPlayer.Character then
        task.spawn(function()
            task.wait(0.05)
            if getgenv().PaidCharacterShield then
                local character = Players.LocalPlayer.Character
                if character.PrimaryPart then
                    character.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end)
    end
end


-- ==========================================================================
-- ENRIQUE PAID PROFILE ENGINE
-- ==========================================================================
do
    local paidProfiles = {}
    local paidProfileIndex = {}
    local paidRetryModes = {Safe = true, Balanced = true, Aggressive = true, Maximum = true}

    local function registerPaidProfile(profile)
        if type(profile) ~= "table" or type(profile.name) ~= "string" then return end
        if paidProfileIndex[profile.name] then return end

        profile.prediction = math.clamp(tonumber(profile.prediction) or 0, -1, 1)
        profile.accuracy = math.clamp(math.floor(tonumber(profile.accuracy) or 20), 1, 50)
        profile.pingMultiplier = math.clamp(tonumber(profile.pingMultiplier) or 1, 0.75, 2.25)
        profile.fastThreshold = math.clamp(math.floor(tonumber(profile.fastThreshold) or 205), 120, 450)

        if not paidRetryModes[profile.retryStrength] then
            profile.retryStrength = "Balanced"
        end

        profile.emergency = profile.emergency == true
        profile.fastShield = profile.fastShield == true
        profile.noStun = profile.noStun == true
        profile.antiAFK = profile.antiAFK == true
        profile.stabilizer = profile.stabilizer == true

        paidProfileIndex[profile.name] = profile
        table.insert(paidProfiles, profile)
    end

    getgenv().ENRIQUE_ProfileCount = function()
        return #paidProfiles
    end

    getgenv().applyENRIQUEPaidProfile = function(name)
        local profile = paidProfileIndex[name]
        if not profile then return false end

        getgenv().AutoParryPredictionMode = "Auto Best"
        getgenv().AutoParryPrediction = profile.prediction
        getgenv().ParryAccuracy = profile.accuracy
        getgenv().PaidEmergencyShield = profile.emergency
        getgenv().PaidPingMultiplier = profile.pingMultiplier
        getgenv().PaidFastBallShield = profile.fastShield
        getgenv().PaidFastBallThreshold = profile.fastThreshold
        getgenv().PaidRetryStrength = profile.retryStrength

        if System and System.__properties then
            System.__properties.__accuracy = profile.accuracy
        end

        if profile.noStun and getgenv().setENRIQUEAntiRagdoll then
            task.spawn(getgenv().setENRIQUEAntiRagdoll, true)
        end

        if profile.antiAFK and getgenv().setENRIQUEAntiAFK then
            task.spawn(getgenv().setENRIQUEAntiAFK, true)
        end

        if profile.stabilizer and getgenv().setENRIQUECharacterShield then
            getgenv().PaidCharacterShield = true
            task.spawn(getgenv().setENRIQUECharacterShield, true)
        end

        getgenv().ENRIQUE_ActivePaidProfile = profile.name
        return true, profile.name
    end

    getgenv().getBestENRIQUEPaidProfile = function(category)
        local player = Players.LocalPlayer
        local pingMs = tonumber(getgenv()._ZX_PingCache) or 55
        local isMobile = false

        pcall(function()
            isMobile = UserInputService.TouchEnabled and not UserInputService.MouseEnabled
        end)

        local best, bestScore
        for _, profile in ipairs(paidProfiles) do
            if category == "All" or profile.category == category then
                local score = 100 - math.abs(profile.prediction * 45)
                    - math.abs(pingMs - profile.referencePing) * 0.055
                    - math.abs(profile.pingMultiplier - (pingMs >= 95 and 1.65 or pingMs <= 35 and 0.92 or 1.22)) * 38

                if profile.emergency then score += 13 end
                if profile.fastShield then score += 11 end
                if profile.noStun then score += 4 end
                if profile.stabilizer then score += 3 end

                if profile.device == "Mobile" and isMobile then score += 24 end
                if profile.device == "PC" and not isMobile then score += 24 end
                if profile.tier == "Paid" then score += 7 end

                if not bestScore or score > bestScore then
                    best, bestScore = profile, score
                end
            end
        end

        return best
    end
