    local assetRing = "rbxassetid://4965945816"

    local function normalizeName(value)
        return string.lower(string.gsub(tostring(value or ""), "[^%w]", ""))
    end

    local function getSwordModule()
        local ok, module = pcall(function()
            return require(game:GetService("ReplicatedStorage").Shared.ReplicatedInstances.Swords)
        end)
        return ok and module or nil
    end

    local function swordFromModule(module, input)
        if not module or type(input) ~= "string" or input == "" then return nil end
        local ok, result = pcall(function()
            return module:GetSword(input)
        end)
        if ok and result then
            return (type(result.Name) == "string" and result.Name ~= "" and result.Name) or input
        end
        return nil
    end

    local function collectShopNames()
        local names = {}
        pcall(function()
            local shop = Players.LocalPlayer:FindFirstChild("PlayerGui"):FindFirstChild("Shop")
            local pages = shop and shop.Holder and shop.Holder:FindFirstChild("Pages")
            for _, pageName in ipairs({"Sword", "Swords", "Explosion", "Explosions"}) do
                local page = pages and pages:FindFirstChild(pageName)
                if page then
                    for _, label in ipairs(page:GetDescendants()) do
                        if label:IsA("TextLabel") and label.Text ~= "" and #label.Text <= 60 then
                            names[label.Text] = true
                        end
                    end
                end
            end
        end)
        return names
    end

    local function resolveSwordName(input)
        local module = getSwordModule()
        local exact = swordFromModule(module, input)
        if exact then return exact, true end

        local wanted = normalizeName(input)
        if wanted ~= "" then
            if module then
                local ok, candidates = pcall(function()
                    local output = {}
                    for _, value in pairs(module) do
                        if type(value) == "table" and type(value.Name) == "string" then
                            table.insert(output, value.Name)
                        end
                    end
                    return output
                end)

                if ok and candidates then
                    for _, candidate in ipairs(candidates) do
                        if normalizeName(candidate) == wanted then return candidate, true end
                    end
                    for _, candidate in ipairs(candidates) do
                        if string.find(normalizeName(candidate), wanted, 1, true) then
                            return candidate, false
                        end
                    end
                end
            end

            for name in pairs(collectShopNames()) do
                if normalizeName(name) == wanted then return name, true end
            end
            for name in pairs(collectShopNames()) do
                if string.find(normalizeName(name), wanted, 1, true) then return name, false end
            end
        end

        return nil
    end

    local function explosionExists(input)
        if type(input) ~= "string" or input == "" then return nil end
        local rs = game:GetService("ReplicatedStorage")
        local wanted = normalizeName(input)
        local roots = {
            rs:FindFirstChild("Misc") and rs.Misc:FindFirstChild("DataExplosions"),
            rs:FindFirstChild("ExplosionEffects"),
            rs.Shared and rs.Shared.ReplicatedInstances and rs.Shared.ReplicatedInstances:FindFirstChild("Explosions"),
        }

        for _, root in ipairs(roots) do
            if root then
                for _, child in ipairs(root:GetDescendants()) do
                    if child.Name == input then return child.Name end
                    if normalizeName(child.Name) == wanted then return child.Name end
                end
            end
        end
        return nil
    end

