        box.TextSize = 13
        box.TextXAlignment = Enum.TextXAlignment.Left
        box.PlaceholderText = placeholder
        box.PlaceholderColor3 = Color3.fromRGB(104, 96, 110)
        box.Text = text or ""
        box.TextColor3 = Color3.fromRGB(245, 240, 246)
        box.ClipsDescendants = true
        box.Parent = frame

        frame.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement then
                TweenService:Create(stroke, TweenInfo.new(0.16), {Color = Color3.fromRGB(190, 55, 85)}):Play()
            end
        end)
        frame.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement then
                TweenService:Create(stroke, TweenInfo.new(0.22), {Color = Color3.fromRGB(72, 62, 74)}):Play()
            end
        end)

        return box, stroke
    end

    local swordBox = field(1, "SWORD NAME  ·  exact or partial", getgenv().swordModel)
    local explosionBox = field(2, "EXPLOSION / KILL FX NAME", getgenv().explosionFX)

    local buttonRow = Instance.new("Frame")
    buttonRow.Size = UDim2.new(1, 0, 0, 46)
    buttonRow.BackgroundTransparency = 1
    buttonRow.LayoutOrder = 3
    buttonRow.Parent = body

    local rowLayout = Instance.new("UIListLayout", buttonRow)
    rowLayout.FillDirection = Enum.FillDirection.Horizontal
    rowLayout.Padding = UDim.new(0, 10)

    local function makeButton(parent, text, color, weight)
        local button = Instance.new("TextButton")
        button.Size = UDim2.fromScale(weight, 1)
        button.BackgroundColor3 = color
        button.BorderSizePixel = 0
        button.AutoButtonColor = false
        button.Font = Enum.Font.GothamBold
        button.TextSize = 12
        button.TextColor3 = Color3.fromRGB(255, 255, 255)
        button.Text = text
        button.Parent = parent
        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 12)

        button.MouseEnter:Connect(function()
            TweenService:Create(button, TweenInfo.new(0.15), {BackgroundColor3 = Color3.new(
                math.min(color.R * 1.22, 1),
                math.min(color.G * 1.22, 1),
                math.min(color.B * 1.22, 1)
            )}):Play()
        end)
        button.MouseLeave:Connect(function()
            TweenService:Create(button, TweenInfo.new(0.22), {BackgroundColor3 = color}):Play()
        end)
        return button
    end

    local swordButton = makeButton(buttonRow, "APPLY SWORD", Color3.fromRGB(205, 34, 64), 0.54)
    local fxButton = makeButton(buttonRow, "APPLY FX", Color3.fromRGB(46, 39, 56), 0.46)

    local bottomRow = Instance.new("Frame")
    bottomRow.Size = UDim2.new(1, 0, 0, 38)
    bottomRow.BackgroundTransparency = 1
    bottomRow.LayoutOrder = 4
    bottomRow.Parent = body

    local resetButton = makeButton(bottomRow, "DISABLE", Color3.fromRGB(33, 29, 39), 0.50)
    local hideButton = makeButton(bottomRow, "HIDE", Color3.fromRGB(33, 29, 39), 0.50)

    local status = Instance.new("TextLabel")
    status.Size = UDim2.new(1, -32, 0, 36)
    status.Position = UDim2.new(0, 16, 1, -44)
    status.BackgroundTransparency = 1
    status.Font = Enum.Font.GothamBold
    status.TextSize = 12
    status.TextWrapped = true
    status.TextXAlignment = Enum.TextXAlignment.Left
    status.TextYAlignment = Enum.TextYAlignment.Top
    status.TextColor3 = Color3.fromRGB(178, 171, 184)
    status.Text = "READY"
    status.Parent = card

    local glowRing = Instance.new("ImageLabel")
    glowRing.AnchorPoint = Vector2.new(0.5, 0.5)
    glowRing.Position = UDim2.fromScale(0.5, 0.5)
    glowRing.Size = UDim2.fromOffset(190, 190)
    glowRing.BackgroundTransparency = 1
    glowRing.Image = assetRing
    glowRing.ImageColor3 = Color3.fromRGB(210, 35, 65)
    glowRing.ImageTransparency = 0.86
    glowRing.Visible = false
    glowRing.Parent = card

    local dragging = false
    local dragStart, startPosition
    card.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPosition = card.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then dragging = false end
            end)
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            local delta = input.Position - dragStart
            card.Position = UDim2.new(startPosition.X.Scale, startPosition.X.Offset + delta.X, startPosition.Y.Scale, startPosition.Y.Offset + delta.Y)
        end
    end)

    local statusToken = 0
    local function setStatus(text, color)
        statusToken += 1
        local token = statusToken
        status.TextColor3 = color or Color3.fromRGB(178, 171, 184)
        task.spawn(function()
            status.Text = ""
            for index = 1, #text do
                if token ~= statusToken then return end
                status.Text = string.sub(text, 1, index)
                task.wait(0.010)
            end
        end)
    end

    local vaultVisible = true
    local function setVault(visible)
        vaultVisible = visible
        if visible then
            orb.Visible = false
            card.Visible = true
            card.GroupTransparency = 1
            card.Position = UDim2.new(card.Position.X.Scale, card.Position.X.Offset, 0.5, 34)
            card.Size = UDim2.fromOffset(386, 400)
            TweenService:Create(card, TweenInfo.new(0.38, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                GroupTransparency = 0,
                Position = UDim2.new(card.Position.X.Scale, card.Position.X.Offset, 0.5, 0),
                Size = UDim2.fromOffset(418, 438),
            }):Play()
            setStatus("VAULT ONLINE", Color3.fromRGB(120, 235, 165))
        else
            local closeAnimation = TweenService:Create(card, TweenInfo.new(0.20, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
                GroupTransparency = 1,
                Size = UDim2.fromOffset(378, 394),
            })
            closeAnimation:Play()
            closeAnimation.Completed:Once(function()
                if not vaultVisible then
                    card.Visible = false
                    orb.Visible = true
                end
            end)
        end
    end

    closeButton.MouseButton1Click:Connect(function() setVault(false) end)
    hideButton.MouseButton1Click:Connect(function() setVault(false) end)
    orb.MouseButton1Click:Connect(function() setVault(true) end)

    local ringAnimation = TweenService:Create(
        glowRing,
        TweenInfo.new(5.8, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1),
        {Rotation = 360}
    )
    ringAnimation:Play()

    local strokeAnimation = TweenService:Create(
        cardStroke,
        TweenInfo.new(1.55, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
        {Transparency = 0.52, Thickness = 2.4}
    )
    strokeAnimation:Play()

    screenGui.Destroying:Connect(function()
        ringAnimation:Cancel()
        strokeAnimation:Cancel()
        if getgenv()._ENRIQUE_SkinVaultGui == screenGui then
            getgenv()._ENRIQUE_SkinVaultGui = nil
        end
    end)
    getgenv()._ENRIQUE_SkinVaultGui = screenGui

    local applying = false
    local function applySword()
        if applying then return end
        local rawInput = string.gsub(swordBox.Text, "^%s*(.-)%s*$", "%1")
        if rawInput == "" then
            setStatus("ENTER A SWORD NAME", Color3.fromRGB(255, 124, 140))
            return
        end

        applying = true
        swordButton.Text = "CHECKING..."
        setStatus("CONNECTING UNLOCK BACKEND", Color3.fromRGB(150, 195, 255))
        if not ensureBackend() then
            applying = false
            swordButton.Text = "APPLY SWORD"
            setStatus("BACKEND NOT READY", Color3.fromRGB(255, 116, 132))
            return
        end

        local resolved, exact = resolveSwordName(rawInput)
        if not resolved then
            applying = false
            swordButton.Text = "APPLY SWORD"
            setStatus("SWORD NOT FOUND", Color3.fromRGB(255, 116, 132))
            return
        end

        swordBox.Text = resolved
        getgenv().skinChanger = true
        getgenv().swordModel = resolved
        getgenv().swordAnimations = resolved
        getgenv().swordFX = resolved

        local module = getSwordModule()
        pcall(function()
            local data = module and module:GetSword(resolved)
            getgenv().slashName = data and data.SlashName or "SlashEffect"
        end)

        setStatus(exact and ("APPLYING " .. string.upper(resolved)) or ("MATCHED " .. string.upper(resolved)), Color3.fromRGB(150, 195, 255))
        local applied = false
        pcall(function()
            getgenv().updateSword()
            applied = true
        end)

        task.delay(0.45, function()
            applying = false
            swordButton.Text = "APPLY SWORD"
            setStatus(applied and ("SWORD ACTIVE · " .. string.upper(resolved)) or "SWORD APPLY FAILED", applied and Color3.fromRGB(120, 235, 165) or Color3.fromRGB(255, 116, 132))
        end)
    end

    local function applyExplosion()
        if applying then return end
        local rawInput = string.gsub(explosionBox.Text, "^%s*(.-)%s*$", "%1")
        if rawInput == "" then
            setStatus("ENTER AN EXPLOSION NAME", Color3.fromRGB(255, 124, 140))
            return
        end

        applying = true
        fxButton.Text = "CHECKING..."
        setStatus("RESOLVING EXPLOSION", Color3.fromRGB(150, 195, 255))
        if not ensureBackend() then
            applying = false
            fxButton.Text = "APPLY FX"
            setStatus("BACKEND NOT READY", Color3.fromRGB(255, 116, 132))
            return
        end

        local resolved = explosionExists(rawInput)
        if not resolved then
            applying = false
            fxButton.Text = "APPLY FX"
            setStatus("EXPLOSION NOT FOUND", Color3.fromRGB(255, 116, 132))
            return
        end

        explosionBox.Text = resolved
        getgenv().explosionChanger = true
        getgenv().explosionFX = resolved

        local fired = false
        pcall(function()
            fired = getgenv().updateExplosion() == true
        end)

        task.delay(0.25, function()
            applying = false
            fxButton.Text = "APPLY FX"
            setStatus("FX ACTIVE · " .. string.upper(resolved), Color3.fromRGB(120, 235, 165))
        end)
    end

    local function disableChangers()
        getgenv().skinChanger = false
        getgenv().explosionChanger = false
        getgenv().swordModel = ""
        getgenv().swordAnimations = ""
        getgenv().swordFX = ""
        getgenv().explosionFX = ""
        swordBox.Text = ""
        explosionBox.Text = ""
        setStatus("CHANGERS DISABLED ON NEXT RESPAWN", Color3.fromRGB(255, 196, 120))
    end

    getgenv().openENRIQUESkinVault = function()
        setVault(true)
    end

    getgenv().closeENRIQUESkinVault = function()
        setVault(false)
    end

    swordButton.MouseButton1Click:Connect(applySword)
    fxButton.MouseButton1Click:Connect(applyExplosion)
    resetButton.MouseButton1Click:Connect(disableChangers)
    swordBox.FocusLost:Connect(function(submitted) if submitted then applySword() end end)
    explosionBox.FocusLost:Connect(function(submitted) if submitted then applyExplosion() end end)

    setVault(true)
end

local ThemeState = {
    AccentHue = (5*43),
    Transparency = 0,
    CornerRadius = (2*6)
}

local function getThemeColor()
    return Color3.fromHSV((ThemeState.AccentHue % (2*180)) / (2*180), 0.62, 0.92)
end

local function applyTheme()
    local root = library._ui
    if not root then return end
if (#"">2) then local _q={} _q[1]=2 end

    local accent = getThemeColor()
    local transparency = 0.5
    local radius = math.clamp(ThemeState.CornerRadius, 0, (54-30))

    local container = root:FindFirstChild("Container")
    if (1<2) and (container) then
        container.BackgroundTransparency = transparency
        local containerCorner = container:FindFirstChildOfClass('UICorner')
        if containerCorner then
            containerCorner.CornerRadius = UDim.new(0, radius)
        end
        local containerStroke = container:FindFirstChildOfClass('UIStroke')
        if containerStroke then
            containerStroke.Color = accent
        end
if (#"">2) then local _n=math.floor(3.14) end
        local side = container:FindFirstChild("GradientSide", true)
        if (math.floor(1.5)==1) and (side) then
            local gradient = side:FindFirstChildOfClass('UIGradient')
            if gradient then
                gradient.Color = ColorSequence.new{
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(bit32.bxor(31,1), (101-71), (17+17))),
                    ColorSequenceKeypoint.new(0.5, accent),
                    ColorSequenceKeypoint.new(1, accent:Lerp(Color3.fromRGB((189-19), (2*45), (3*85)), 0.45))
                }
            end
        end
    end

    for _, object in ipairs(root:GetDescendants()) do
        if object:IsA('UICorner') then
            local parent = object.Parent
            if (#{1}==1) and (parent and parent.Name ~= 'Circle' and parent.Name ~= 'Toggle' and parent.Name ~= 'Dot' and parent.Name ~= "AvatarClip") then
                object.CornerRadius = UDim.new(0, radius)
            end
        elseif object:IsA('TextLabel') or object:IsA('TextButton') or object:IsA('TextBox') then
            local baseSize = object:GetAttribute("ThemeBaseTextSize")
            if not baseSize then
                baseSize = object.TextSize
                object:SetAttribute("ThemeBaseTextSize", baseSize)
if (#"">2) then local _n=math.floor(3.14) end
            end
            object.TextSize = baseSize
        elseif object:IsA('Frame') and (object.Name == 'Fill' or object.Name == "RangeFill" or object.Name == "ActiveIndicator") then
            object.BackgroundColor3 = accent
        end
    end

    if library._notification_helpers and library._notification_helpers.theme then
        library._notification_helpers.theme.accent = accent
        library._notification_helpers.theme.info = accent
        library._notification_helpers.theme.radius = UDim.new(0, radius)
    end
end

local function resetThemeDefaults()
    ThemeState.AccentHue = (5*43)
    ThemeState.Transparency = 50
    ThemeState.CornerRadius = (2*6)
if ((1/1)==0) then local _q={} _q[1]=2 end

    if (1<2) and (Library._config and Library._config._flags) then
        Library._config._flags.ThemeAccentHue = ThemeState.AccentHue
        Library._config._flags.ThemeTransparency = ThemeState.Transparency
        Library._config._flags.ThemeCornerRadius = ThemeState.CornerRadius
        Config:save(game.GameId, Library._config)
    end

    applyTheme()
end

