    local original_fog_end = Lighting.FogEnd
local original_fog_start = Lighting.FogStart
local postprocessing_backup = {}
local decals_backup = {}

-- ==========================================================================
-- ENRIQUE PAID PERFORMANCE ENGINE
-- ==========================================================================
do
    local performance = {
        enabled = false,
        mode = "Balanced",
        adaptive = false,
        connections = {},
        objectBackup = setmetatable({}, {__mode = "k"}),
        lightingBackup = nil,
        terrainBackup = nil,
        qualityBackup = nil,
        frameTime = 0,
        frames = 0,
        lastAdapt = 0,
        appliedObjects = 0,
    }

    getgenv().ENRIQUE_Performance = performance
    local modeRank = {Balanced = 1, Ultra = 2, Extreme = 3, Nuclear = 4}

    local function saveProperty(object, property)
        local data = performance.objectBackup[object]
        if not data then
            data = {}
            performance.objectBackup[object] = data
        end

        if data[property] == nil then
            local ok, value = pcall(function()
                return object[property]
            end)
            if ok then data[property] = value end
        end
    end

    local function setProperty(object, property, value)
        saveProperty(object, property)
        pcall(function()
            object[property] = value
        end)
    end

    local function shouldProcess(object)
        if object:IsA("ParticleEmitter") or object:IsA("Fire") or object:IsA("Smoke") or object:IsA("Sparkles") then return true end
        if object:IsA("Trail") or object:IsA("Beam") or object:IsA("Highlight") then return true end

        if modeRank[performance.mode] >= 2 then
            if object:IsA("Decal") or object:IsA("Texture") or object:IsA("SurfaceGui") or object:IsA("BillboardGui") then return true end
        end

        if modeRank[performance.mode] >= 3 then
            if object:IsA("BasePart") or object:IsA("MeshPart") then return true end
            if object:IsA("PointLight") or object:IsA("SpotLight") or object:IsA("SurfaceLight") then return true end
        end

        return false
    end

    local function applyObject(object)
        if not shouldProcess(object) then return end

        if object:IsA("ParticleEmitter") then
            setProperty(object, "Rate", 0)
        elseif object:IsA("Fire") or object:IsA("Smoke") or object:IsA("Sparkles") then
            setProperty(object, "Enabled", false)
        elseif object:IsA("Trail") or object:IsA("Beam") or object:IsA("Highlight")
            or object:IsA("SurfaceGui") or object:IsA("BillboardGui") then
            setProperty(object, "Enabled", false)
        elseif object:IsA("Decal") or object:IsA("Texture") then
            setProperty(object, "Transparency", 1)
        elseif object:IsA("BasePart") or object:IsA("MeshPart") then
            setProperty(object, "CastShadow", false)

            if modeRank[performance.mode] >= 4 and not object:IsA("Terrain") then
                setProperty(object, "Material", Enum.Material.SmoothPlastic)
                setProperty(object, "Reflectance", 0)
            end
        elseif object:IsA("PointLight") or object:IsA("SpotLight") or object:IsA("SurfaceLight") then
            setProperty(object, "Enabled", false)
        end

        performance.appliedObjects += 1
    end

    local function scanContainer(container)
        for _, object in ipairs(container:GetDescendants()) do
            pcall(applyObject, object)
        end
    end

    local function saveSceneSettings()
        if not performance.lightingBackup then
            performance.lightingBackup = {
                GlobalShadows = Lighting.GlobalShadows,
                FogEnd = Lighting.FogEnd,
                FogStart = Lighting.FogStart,
                ShadowSoftness = Lighting.ShadowSoftness,
                EnvironmentDiffuseScale = Lighting.EnvironmentDiffuseScale,
                EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale,
            }
        end

        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain and not performance.terrainBackup then
            performance.terrainBackup = {
                WaterWaveSize = terrain.WaterWaveSize,
                WaterWaveSpeed = terrain.WaterWaveSpeed,
                WaterReflectance = terrain.WaterReflectance,
                WaterTransparency = terrain.WaterTransparency,
            }
        end

        pcall(function()
            if not performance.qualityBackup then
                performance.qualityBackup = settings().Rendering.QualityLevel
            end
        end)
    end

    local function applyLighting()
        saveSceneSettings()

        pcall(function()
            Lighting.GlobalShadows = false
            Lighting.ShadowSoftness = 0
            Lighting.EnvironmentDiffuseScale = modeRank[performance.mode] >= 3 and 0 or 0.15
            Lighting.EnvironmentSpecularScale = modeRank[performance.mode] >= 3 and 0 or 0.20
            Lighting.FogEnd = math.huge
            Lighting.FogStart = math.huge
        end)

        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain then
            setProperty(terrain, "WaterWaveSize", 0)
            setProperty(terrain, "WaterWaveSpeed", 0)
            setProperty(terrain, "WaterReflectance", 0)
            setProperty(terrain, "WaterTransparency", modeRank[performance.mode] >= 3 and 1 or 0.65)
        end

        pcall(function()
            settings().Rendering.QualityLevel = modeRank[performance.mode] >= 3
                and Enum.QualityLevel.Level01
                or Enum.QualityLevel.Level04
        end)
    end

    local function restoreObject(object)
        local values = performance.objectBackup[object]
        if not values then return end

        for property, value in pairs(values) do
            pcall(function()
                object[property] = value
            end)
        end

        performance.objectBackup[object] = nil
    end

    getgenv().applyENRIQUEPerformance = function(enabled, mode)
        enabled = enabled == true
        mode = mode or performance.mode
        performance.mode = mode

        if performance.connections.descendants then
            performance.connections.descendants:Disconnect()
            performance.connections.descendants = nil
        end

        if not enabled then
            for object in pairs(performance.objectBackup) do
                restoreObject(object)
            end

            if performance.lightingBackup then
                for property, value in pairs(performance.lightingBackup) do
                    pcall(function()
                        Lighting[property] = value
                    end)
                end
                performance.lightingBackup = nil
            end

            local terrain = workspace:FindFirstChildOfClass("Terrain")
            if terrain and performance.terrainBackup then
                for property, value in pairs(performance.terrainBackup) do
                    pcall(function()
                        terrain[property] = value
                    end)
                end
                performance.terrainBackup = nil
            end

            pcall(function()
                if performance.qualityBackup then
                    settings().Rendering.QualityLevel = performance.qualityBackup
                    performance.qualityBackup = nil
                end
            end)

            performance.enabled = false
            performance.appliedObjects = 0
            getgenv().ENRIQUE_PerformanceStatus = "OFF"
            return true
        end

        performance.enabled = true
        applyLighting()
        scanContainer(workspace)

        performance.connections.descendants = workspace.DescendantAdded:Connect(function(object)
            task.defer(function()
                if performance.enabled then
                    pcall(applyObject, object)
                end
            end)
        end)

        getgenv().ENRIQUE_PerformanceStatus = mode .. " · " .. tostring(performance.appliedObjects) .. " objects"
        return true, getgenv().ENRIQUE_PerformanceStatus
    end

    getgenv().setENRIQUEAdaptivePerformance = function(enabled)
        performance.adaptive = enabled == true

        if performance.connections.adaptive then
            performance.connections.adaptive:Disconnect()
            performance.connections.adaptive = nil
        end

        if not performance.adaptive then return end

        performance.frameTime = 0
        performance.frames = 0
        performance.lastAdapt = os.clock()

        performance.connections.adaptive = RunService.RenderStepped:Connect(function(delta)
            if not performance.enabled then return end

            performance.frameTime += delta
            performance.frames += 1

            if performance.frameTime < 1 then return end
            local fps = performance.frames / performance.frameTime
            performance.frameTime = 0
            performance.frames = 0
            getgenv().ENRIQUE_AdaptiveFPS = math.floor(fps + 0.5)

            if os.clock() - performance.lastAdapt < 2.5 then return end

            local requested = performance.mode
            if fps <= 28 then
                requested = "Nuclear"
            elseif fps <= 44 then
                requested = "Extreme"
            elseif fps <= 56 then
                requested = "Ultra"
            elseif fps >= 78 and performance.mode ~= "Nuclear" then
                requested = "Balanced"
            end

            if requested ~= performance.mode then
                performance.lastAdapt = os.clock()
                getgenv().applyENRIQUEPerformance(true, requested)
            else
                performance.lastAdapt = os.clock()
            end
        end)

        getgenv().ENRIQUE_PerformanceStatus = "Adaptive ON"
    end

    getgenv().runOneTimeENRIQUECleanup = function()
        local before = performance.appliedObjects
        scanContainer(workspace)
        getgenv().ENRIQUE_PerformanceStatus = "Cleanup · +" .. tostring(performance.appliedObjects - before)
        return true, getgenv().ENRIQUE_PerformanceStatus
    end
end

