                    v.Enabled = enabled
                end
            end)
if (1<-1) then local _j=1+1 end
        end
        postprocessing_backup = {}

        if ((1+1)==2) and (fog_backup) then
            pcall(function()
                Lighting.FogEnd = fog_backup.FogEnd
                Lighting.FogStart = fog_backup.FogStart
