function System.ball.get_prediction(ball, root)
    local ok, result = pcall(function()
        local zoomies = ball:FindFirstChild("zoomies")
        if not zoomies then return nil end

        local now = tick()
        local position = ball.Position
        local rawVelocity = zoomies.VectorVelocity
        local rawAcceleration = Vector3.zero
        local track = System.__properties.__ball_track[ball]
        local hitRadius = 11

        if track and track.position and track.time and now > track.time then
            local delta = math.clamp(now - track.time, 0.001, 0.20)
            local observedVelocity = (position - track.position) / delta
            if observedVelocity.Magnitude > 1 and observedVelocity.Magnitude < 5000 then
                rawVelocity = rawVelocity:Lerp(observedVelocity, 0.36)

                if track.velocity then
                    local observedAcceleration = (observedVelocity - track.velocity) / delta
                    if observedAcceleration.Magnitude < 6500 then
                        rawAcceleration = (track.acceleration or Vector3.zero):Lerp(observedAcceleration, 0.24)
                    end
                end
            end
        end

        local segmentDistance = math.huge
        local crossedHitSphere = false
        if track and track.position then
            local motion = position - track.position
            local travel = motion.Magnitude
            if travel > 0.001 then
                local toPrevious = track.position - root.Position
                local segmentTime = math.clamp(-toPrevious:Dot(motion) / (travel * travel), 0, 1)
                local nearestPoint = track.position + motion * segmentTime
                segmentDistance = (nearestPoint - root.Position).Magnitude
                crossedHitSphere = segmentDistance <= hitRadius * 1.45
            end
        end

        System.__properties.__ball_track[ball] = {
            position = position,
            time = now,
            velocity = rawVelocity,
            acceleration = rawAcceleration,
        }

        local rootVelocity = root.AssemblyLinearVelocity or Vector3.zero
        local relativePosition = position - root.Position
        local relativeVelocity = rawVelocity - rootVelocity
        local relativeAcceleration = rawAcceleration
        local speed = rawVelocity.Magnitude
        local a = relativeVelocity:Dot(relativeVelocity)
        local b = 2 * relativePosition:Dot(relativeVelocity)
        local c = relativePosition:Dot(relativePosition) - hitRadius * hitRadius
        local eta = math.huge
        local closestDistance = relativePosition.Magnitude

        if a > 0.01 then
            local discriminant = b * b - 4 * a * c
            if discriminant >= 0 then
                local squareRoot = math.sqrt(discriminant)
                local first = (-b - squareRoot) / (2 * a)
                local second = (-b + squareRoot) / (2 * a)
                if first >= 0 and second >= 0 then
                    eta = math.min(first, second)
                elseif first >= 0 then
                    eta = first
                elseif second >= 0 then
                    eta = second
                end
            end

            local closestTime = math.clamp(-b / (2 * a), 0, 1)
            closestDistance = (relativePosition + relativeVelocity * closestTime).Magnitude
        end

        local sampledImpactDistanceSq = math.huge
        local coarseStep = 1 / 38
        local hitStep = -1
        local previousStep = 0

        for step = 0, 18 do
            local sampleTime = step * coarseStep
            local predictedOffset = relativePosition
                + relativeVelocity * sampleTime
                + relativeAcceleration * (sampleTime * sampleTime * 0.5)
            local sampleDistanceSq = predictedOffset:Dot(predictedOffset)

            if sampleDistanceSq < sampledImpactDistanceSq then
                sampledImpactDistanceSq = sampleDistanceSq
            end

            if sampleDistanceSq <= (hitRadius * 1.12) ^ 2 then
                eta = math.min(eta, sampleTime)
                hitStep = step
                break
            end

            previousStep = sampleTime
        end

        if hitStep > 0 then
            local refinedStart = previousStep
            local refinedEnd = hitStep * coarseStep
            local refinedStep = (refinedEnd - refinedStart) / 8

            for step = 1, 8 do
                local sampleTime = refinedStart + refinedStep * step
                local predictedOffset = relativePosition
                    + relativeVelocity * sampleTime
                    + relativeAcceleration * (sampleTime * sampleTime * 0.5)
                local sampleDistanceSq = predictedOffset:Dot(predictedOffset)

                if sampleDistanceSq <= (hitRadius * 1.12) ^ 2 then
                    eta = math.min(eta, sampleTime)
                    break
                end
            end
        end

        closestDistance = math.min(closestDistance, math.sqrt(sampledImpactDistanceSq))

        local direction = speed > 1 and rawVelocity.Unit or Vector3.zero
        local toRoot = root.Position - position
        local approaching = toRoot.Magnitude < 0.5 or (toRoot.Magnitude > 0 and direction:Dot(toRoot.Unit) > -0.15)

        return {
            eta = math.clamp(eta, 0, 2),
            closestDistance = math.min(closestDistance, segmentDistance),
            speed = speed,
            velocity = rawVelocity,
            approaching = approaching or crossedHitSphere,
            crossed = crossedHitSphere,
        }
    end)

    return ok and result or nil
end

