System.manual_spam = {}

function System.manual_spam.loop(delta)
    if not System.__properties.__manual_spam_enabled then return end
    if not LocalPlayer.Character or LocalPlayer.Character.Parent ~= Alive then return end
    if getgenv().spamui then return end

    local now = tick()
    local last = System.__properties.__manual_last_frame or now
    local frameDelta = delta or (now - last)
    System.__properties.__manual_last_frame = now

    frameDelta = math.clamp(frameDelta, 0, 0.25)
    System.__properties.__manual_spam_accumulator = math.min(
        (System.__properties.__manual_spam_accumulator or 0) + frameDelta,
        0.25
    )

    local interval
    if getgenv().ManualSpamCPSEnabled then
        interval = get_manual_spam_interval()
    else
        interval = 1 / math.max(1, System.__properties.__spam_rate or 1000)
    end

    local quota = (System.__properties.__manual_spam_accumulator or 0) / interval
    if quota < 1 then return end

    local fpsGuess = 1 / math.max(frameDelta, 1 / 240)
    local maxPerFrame = 128
    local count = math.min(math.floor(quota), maxPerFrame, math.ceil(fpsGuess / 2) + 8)
    if count < 1 then return end

    System.__properties.__manual_spam_accumulator -= count * interval
    if System.__properties.__manual_spam_accumulator < 0 then
        System.__properties.__manual_spam_accumulator = 0
    end

    send_manual_spam_burst(count)
end

function System.manual_spam.start()
    if System.__properties.__connections.__manual_spam then
        System.__properties.__connections.__manual_spam:Disconnect()
    end
    System.__properties.__manual_spam_enabled = true
    System.__properties.__manual_spam_accumulator = 0
    System.__properties.__manual_last_frame = tick()
    System.__properties.__connections.__manual_spam = RunService.PreSimulation:Connect(System.manual_spam.loop)
end

function System.manual_spam.stop()
    System.__properties.__manual_spam_enabled = false
    System.__properties.__manual_spam_accumulator = 0
    if System.__properties.__connections.__manual_spam then
        System.__properties.__connections.__manual_spam:Disconnect()
        System.__properties.__connections.__manual_spam = nil
    end
end

