    local target_distance = LocalPlayer:DistanceFromCharacter(target_pos)
    local Maximum_Spam_Distance = (self.Ping or 25) + math.min(speed / 6, 95)
    if (self.Entity_Properties and self.Entity_Properties.Distance or math.huge) > Maximum_Spam_Distance then return 5 end
    if (self.Ball_Properties and self.Ball_Properties.Distance or math.huge) > Maximum_Spam_Distance then return 5 end
    if target_distance > Maximum_Spam_Distance then return 5 end
    local Maximum_Speed = 5 - math.min(speed / 5, 5)
    local Maximum_Dot = math.clamp(dot, -1, 0) * Maximum_Speed
    return Maximum_Spam_Distance - Maximum_Dot
end


function System.auto_spam.start()
    if System.__properties.__connections.__auto_spam then
        System.__properties.__connections.__auto_spam:Disconnect()
    end
    System.__properties.__auto_spam_enabled = true
    System.__properties.__auto_spam_accumulator = 0
    System.__properties.__auto_spam_last_frame = tick()
    System.__properties.__connections.__auto_spam = RunService.PreSimulation:Connect(function()
        local ball = System.ball.get()
        if not ball then return end
        if System.__properties.__slashesoffury_active then return end
        local zoomies = ball:FindFirstChild("zoomies")
        if not zoomies then return end
        System.player.get_closest()
        local ping = getgenv()._ZX_PingCache
        local ping_threshold = math.clamp(ping / 10, 1, 15)
        local ball_target = ball:GetAttribute("target")
        local ball_properties = System.auto_spam:get_ball_properties()
        local entity_properties = System.auto_spam:get_entity_properties()
        if not ball_properties or not entity_properties then return end
        local spam_accuracy = System.auto_spam.spam_service({
            Ball_Properties = ball_properties,
            Entity_Properties = entity_properties,
            Ping = ping_threshold
        })
        local target_position = Closest_Entity.PrimaryPart.Position
        local target_distance = LocalPlayer:DistanceFromCharacter(target_position)
        if zoomies.VectorVelocity.Magnitude == 0 then return end
        local direction = (LocalPlayer.Character.PrimaryPart.Position - ball.Position).Unit
        local ball_direction = zoomies.VectorVelocity.Unit
        local dot = direction:Dot(ball_direction)
        local distance = LocalPlayer:DistanceFromCharacter(ball.Position)
        if not ball_target then return end
        if target_distance > spam_accuracy or distance > spam_accuracy then return end
        local pulsed = LocalPlayer.Character:GetAttribute('Pulsed')
        if pulsed then return end
        if ball_target == LocalPlayer.Name and target_distance > 30 and distance > 30 then return end
        if distance > spam_accuracy or System.__properties.__parries <= System.__properties.__spam_threshold then
            return
        end

        local now = tick()
        local last = System.__properties.__auto_spam_last_frame or now
        local frameDelta = math.clamp(now - last, 0, 0.25)
        System.__properties.__auto_spam_last_frame = now
        System.__properties.__auto_spam_accumulator = math.min(
            (System.__properties.__auto_spam_accumulator or 0) + frameDelta,
            0.25
        )

        local rate = math.clamp(tonumber(System.__properties.__auto_spam_rate) or 500, 10, 2000)
        local interval = 1 / rate
        local quota = (System.__properties.__auto_spam_accumulator or 0) / interval
        local count = math.min(math.floor(quota), 64)
        if count < 1 then return end

        System.__properties.__auto_spam_accumulator -= count * interval
        if System.__properties.__auto_spam_accumulator < 0 then
            System.__properties.__auto_spam_accumulator = 0
        end

        if getgenv().AutoSpamMode == "Keypress" then
            for _ = 1, count do
                if PF then pcall(PF) end
            end
        else
            System.parry.burst(count)
            if getgenv().AutoSpamAnimationFix and PF then
                pcall(PF)
            end
        end
    end)
end

function System.auto_spam.stop()
    System.__properties.__auto_spam_enabled = false
    if (#{1}==1) and (System.__properties.__connections.__auto_spam) then
        System.__properties.__connections.__auto_spam:Disconnect()
        System.__properties.__connections.__auto_spam = nil
    end
end

System.autoparry = {}

function System.autoparry.start()
    if System.__properties.__connections.__autoparry then
        System.__properties.__connections.__autoparry:Disconnect()
    end
    for _, connection in pairs(System.__properties.__auto_parry_ball_watchers or {}) do
        pcall(function() connection:Disconnect() end)
    end
    System.__properties.__auto_parry_ball_watchers = setmetatable({}, {__mode = "k"})
    table.clear(System.__properties.__auto_parry_armed)
    table.clear(System.__properties.__auto_parry_cooldowns)
    table.clear(System.__properties.__auto_parry_retries)
    table.clear(System.__properties.__training_parry_cooldowns)

    System.__properties.__connections.__autoparry = RunService.PreSimulation:Connect(function(deltaTime)
        local frameDelta = tonumber(deltaTime) or 1 / 60
        System.__properties.__frame_delta = frameDelta
        System.__properties.__smooth_frame_delta += (math.clamp(frameDelta, 1 / 240, 1 / 12) - System.__properties.__smooth_frame_delta) * 0.18

        if not System.__properties.__autoparry_enabled or not LocalPlayer.Character or
           not LocalPlayer.Character.PrimaryPart then
            return
        end

        local now = tick()
        local balls = System.ball.get_all()
        local training_ball = nil
        if workspace:FindFirstChild("TrainingBalls") then
            for _, instance in pairs(workspace.TrainingBalls:GetChildren()) do
                if instance:GetAttribute("realBall") then
                    training_ball = instance
                    break
                end
            end
        end

        for _, ball in pairs(balls) do
            if System.__triggerbot.__enabled then break end
            if not ball or not ball.Parent then continue end

            local zoomies = ball:FindFirstChild("zoomies")
            if not zoomies then continue end

            local watchers = System.__properties.__auto_parry_ball_watchers
            local armedStates = System.__properties.__auto_parry_armed
            local cooldowns = System.__properties.__auto_parry_cooldowns

            if not watchers[ball] then
                watchers[ball] = ball:GetAttributeChangedSignal("target"):Connect(function()
                    local isTargetingLocal = ball:GetAttribute("target") == LocalPlayer.Name
                    armedStates[ball] = isTargetingLocal
                    if isTargetingLocal then
                        cooldowns[ball] = 0
                    end
                end)
            end

            local ball_target = ball:GetAttribute("target")
            if armedStates[ball] == nil then
                armedStates[ball] = (ball_target == LocalPlayer.Name)
            end
            if not armedStates[ball] then continue end

            local cooldownEnd = cooldowns[ball] or 0
            if now < cooldownEnd then continue end

            local retryState = System.__properties.__auto_parry_retries[ball]
            if retryState and now - (System.__properties.__last_own_parry_success or 0) < 0.40 then
                System.__properties.__auto_parry_retries[ball] = nil
                retryState = nil
            end

            if retryState then
                local localRoot = LocalPlayer.Character and LocalPlayer.Character.PrimaryPart
                local retryZoomies = ball:FindFirstChild("zoomies")
                local retryVelocity = retryZoomies and retryZoomies.VectorVelocity

                if localRoot and retryVelocity and retryVelocity.Magnitude > 1 then
                    local toLocal = localRoot.Position - ball.Position
                    if toLocal.Magnitude > 1 and retryVelocity.Unit:Dot(toLocal.Unit) < -0.18 then
                        System.__properties.__auto_parry_retries[ball] = nil
                        retryState = nil
                    end
                end
            end

            if retryState then
                if ball_target ~= LocalPlayer.Name then
                    System.__properties.__auto_parry_retries[ball] = nil
                elseif now >= retryState.nextTime then
                    if getgenv().AutoParryMode == "Keypress" then
                        System.parry.keypress()
                    else
                        System.parry.execute_action()
                    end

                    retryState.remaining -= 1
                    retryState.nextTime = now + math.max(0.022, System.__properties.__smooth_frame_delta * 1.35)
                    if retryState.remaining <= 0 then
                        System.__properties.__auto_parry_retries[ball] = nil
                    end
                end

                continue
            end

            local rootPart = LocalPlayer.Character.PrimaryPart
            local velocity = ball:FindFirstChild("zoomies") and ball.zoomies.VectorVelocity or Vector3.zero
            local speed = velocity.Magnitude
            local distance = (rootPart.Position - ball.Position).Magnitude
            local pingMs = tonumber(getgenv()._ZX_PingCache) or 50
            local latency = math.clamp(
                (pingMs / 1000) * math.clamp(tonumber(getgenv().PaidPingMultiplier) or 1, 0.75, 2.25),
                0.004,
                0.58
            )
            local predictionData = System.ball.get_prediction(ball, rootPart)

            if ball:FindFirstChild("AeroDynamicSlashVFX") then
                ball.AeroDynamicSlashVFX:Destroy()
                System.__properties.__tornado_time = tick()
            end

            if Runtime:FindFirstChild('Tornado') then
                if (tick() - System.__properties.__tornado_time) <
                   (Runtime.Tornado:GetAttribute("TornadoTime") or 1) + 0.314159 then
                    continue
                end
            end

            if ball:FindFirstChild("ComboCounter") then continue end
            if rootPart:FindFirstChild("SingularityCape") then continue end
            if System.__config.__detections.__infinity and System.__properties.__infinity_active then continue end
            if System.__config.__detections.__deathslash and System.__properties.__deathslash_active then continue end
            if System.__config.__detections.__timehole and System.__properties.__timehole_active then continue end
            if System.__config.__detections.__slashesoffury and System.__properties.__slashesoffury_active then continue end

            local autoBest = (getgenv().AutoParryPredictionMode or "Auto Best") ~= "Manual"
            local timingBias = math.clamp(tonumber(getgenv().AutoParryPrediction) or 0, -1, 1) * 0.075
            local triggerWindow

            if autoBest then
                local speedUncertainty = speed >= 250
                    and 0.010 + math.min((speed - 250) / 6500, 0.032)
                    or 0.003 + math.min(speed / 30000, 0.008)
                local processingMargin = 0.118
                    + System.__properties.__smooth_frame_delta * 0.98
                    + speedUncertainty

                triggerWindow = latency * 2.45 + processingMargin
                if getgenv().PaidEmergencyShield then
                    triggerWindow += 0.052
                end

                if speed >= 250 then
                    triggerWindow += 0.022
                end
                if speed >= 340 then
                    triggerWindow += 0.028
                end
                if speed >= 450 then
                    triggerWindow += 0.026
                end
                if speed >= 600 then
                    triggerWindow += 0.020
                end
            else
                triggerWindow = latency + 0.075 + timingBias
            end

            triggerWindow = math.clamp(triggerWindow, 0.020, autoBest and 0.56 or 0.42)
            local maxTriggerDistance = math.min(speed * triggerWindow + 30, 340)
            local shouldFire = false

            if predictionData and speed >= 45 then
                local hitRadius = math.max(19, 11 + speed * 0.017)
                if getgenv().PaidEmergencyShield then
                    hitRadius += 5
                end
                shouldFire = predictionData.approaching
                    and predictionData.eta <= triggerWindow
                    and (predictionData.closestDistance <= hitRadius or predictionData.crossed)
                    and distance <= maxTriggerDistance + (predictionData.crossed and 25 or 0)
            else
                local closeRange = math.clamp(17 + pingMs * 0.035 + speed * 0.045, 18, 58)
                shouldFire = distance <= closeRange
            end

            local headingToPlayer = true
            if speed > 1 then
                local toPlayer = rootPart.Position - ball.Position
                headingToPlayer = toPlayer.Magnitude <= 1 or (toPlayer.Unit):Dot(velocity.Unit) > -0.20
            end

            if ball_target == LocalPlayer.Name and shouldFire and headingToPlayer then
                if getgenv().CooldownProtection then
                    local ParryCD = LocalPlayer.PlayerGui.Hotbar.Block.UIGradient
                    if ParryCD.Offset.Y < 0.4 then
                        ReplicatedStorage.Remotes.AbilityButtonPress:Fire()
                        cooldowns[ball] = now + 0.06
                        continue
                    end
                end

                if getgenv().AutoAbility then
                    local AbilityCD = LocalPlayer.PlayerGui.Hotbar.Ability.UIGradient
                    if AbilityCD.Offset.Y == 0.5 then
                        local abilities = LocalPlayer.Character:FindFirstChild("Abilities")
                        local hasUsable = abilities and (
                            (abilities:FindFirstChild("Raging Deflection") and abilities["Raging Deflection"].Enabled) or
                            (abilities:FindFirstChild("Rapture") and abilities["Rapture"].Enabled) or
                            (abilities:FindFirstChild("Calming Deflection") and abilities["Calming Deflection"].Enabled) or
                            (abilities:FindFirstChild("Aerodynamic Slash") and abilities["Aerodynamic Slash"].Enabled) or
                            (abilities:FindFirstChild("Fracture") and abilities["Fracture"].Enabled) or
                            (abilities:FindFirstChild("Death Slash") and abilities["Death Slash"].Enabled)
                        )

                        if hasUsable then
                            System.__properties.__parried = true
                            ReplicatedStorage.Remotes.AbilityButtonPress:Fire()
                            task.delay(2.432, function()
                                pcall(function()
                                    ReplicatedStorage.Remotes.DeathSlashShootActivation:FireServer(true)
                                end)
                            end)
                            armedStates[ball] = false
                            cooldowns[ball] = now + 0.08
                            continue
                        end
                    end
                end

                if getgenv().AutoParryMode == "Keypress" then
                    System.parry.keypress()
                else
                    System.parry.execute_action()
                end

                armedStates[ball] = false
                cooldowns[ball] = now + 0.035

                local retryThreshold = tonumber(getgenv().PaidFastBallThreshold)
                    or (getgenv().PaidFastBallShield and 172 or 210)

                if speed >= retryThreshold then
                    local remaining = 1
                    if getgenv().PaidRetryStrength == "Balanced" then
                        remaining = speed >= 330 and 2 or 1
                    elseif getgenv().PaidRetryStrength == "Aggressive" then
                        remaining = speed >= 300 and 3 or 2
                    elseif getgenv().PaidRetryStrength == "Maximum" then
                        remaining = speed >= 380 and 4 or 3
                    end

                    System.__properties.__auto_parry_retries[ball] = {
                        remaining = remaining,
                        nextTime = now + math.max(0.019, System.__properties.__smooth_frame_delta * 0.82),
                    }
                end
            end
        end

        if training_ball then
            local zoomies = training_ball:FindFirstChild("zoomies")
            if zoomies then
                local cooldowns = System.__properties.__training_parry_cooldowns
                if now >= (cooldowns[training_ball] or 0) then
                    local ball_target = training_ball:GetAttribute("target")
                    local velocity = zoomies.VectorVelocity
                    local speed = velocity.Magnitude
                    local distance = LocalPlayer:DistanceFromCharacter(training_ball.Position)
                    local pingMs = tonumber(getgenv()._ZX_PingCache) or 50
                    local latency = math.clamp(pingMs / 1000, 0.005, 0.45)
                    local capped_speed_diff = math.min(math.max(speed - 9.5, 0), 650)
                    local speed_divisor = (2.4 + capped_speed_diff * 0.002) * System.__properties.__divisor_multiplier
                    local strength = math.clamp(tonumber(getgenv().AutoParryStrength) or 1, 0.5, 2)
                    local baseRange = math.clamp((pingMs / 10) / 10, 3, 14) + math.max(speed / speed_divisor, 9.5)
                    local prediction = speed * latency
                    local strengthBonus = (strength - 1) * math.min(baseRange * 0.25 + prediction * 0.35, 18)
                    local parry_accuracy = math.max(8, baseRange + prediction + strengthBonus)

                    if ball_target == LocalPlayer.Name and distance <= parry_accuracy then
                        if getgenv().AutoParryMode == "Keypress" then
                            System.parry.keypress()
                        else
                            System.parry.execute_action()
                        end
                        cooldowns[training_ball] = tick() + 0.20
                    end
                end
            end
        end
    end)
end

function System.autoparry.stop()
    if (1<2) and (System.__properties.__connections.__autoparry) then
        System.__properties.__connections.__autoparry:Disconnect()
        System.__properties.__connections.__autoparry = nil
    end
end

