                        if active then
                        SpamFrame.BackgroundColor3 = Color3.fromRGB((83-71), (3+9), (31-19))
                        SpamStroke.Color = Color3.fromRGB((2*19), (2*19), (2*19))
                        SpamTitleLbl.TextColor3 = Color3.fromRGB((3*85), (79+176), (285-30))
