                        SpamToggleStroke.Color = Color3.fromRGB((2*50), (2*110), (79+51))
                    else
                        SpamFrame.BackgroundColor3 = Color3.fromRGB((42-30), bit32.bxor(31,19), (83-71))
                        SpamStroke.Color = Color3.fromRGB((27+11), (57-19), (2*19))
