local AUTO_BEST_RARITY_SCORES = {
    secret = 7000, mythic = 6000, divine = 5200, celestial = 4800,
    legendary = 4200, epic = 3400, rare = 2400, uncommon = 1400, common = 400,
}

local function scoreRarityText(text)
    text = string.lower(tostring(text or ""))
    local best = 0
    for word, score in pairs(AUTO_BEST_RARITY_SCORES) do
        if string.find(text, word, 1, true) then
            best = math.max(best, score)
        end
    end

    return best
end

local function scoreNumericText(text)
    local cleaned = tostring(text or ""):gsub("[,%s]", "")
    local best = 0
    for value in cleaned:gmatch("%d+") do
        local number = tonumber(value)
        if number and number > best and number < 1e12 then
            best = number
        end
    end

    return math.min(best / 1000000, 2200)
end

local function getSwordCardCandidates()
    local cards = {}

    pcall(function()
        local playerGui = LocalPlayer:FindFirstChild("PlayerGui")
        local shop = playerGui and (playerGui:FindFirstChild("Shop") or playerGui:FindFirstChild("ShopGui"))
        local holder = shop and shop:FindFirstChild("Holder")
        local pages = holder and holder:FindFirstChild("Pages")
        local page = pages and (pages:FindFirstChild("Sword") or pages:FindFirstChild("Swords"))
        local owned = page and page:FindFirstChild("Owned", true)

        if owned then
            for _, card in ipairs(owned:GetChildren()) do
                local title = card:FindFirstChild("Title", true)
                    or card:FindFirstChild("ItemName", true)
                    or card:FindFirstChild("Name", true)
                if card:IsA("GuiObject") and title and title:IsA("TextLabel") and title.Text ~= "" then
                    table.insert(cards, {item = card, name = title.Text, score = 0})
                end
            end
        end
    end)

    return cards
end

local function scoreSwordCandidate(candidate)
    local item = candidate.item
    local score = 0

    if item then
        for _, child in ipairs(item:GetDescendants()) do
            if child:IsA("TextLabel") or child:IsA("TextBox") then
                score += scoreRarityText(child.Text) * 0.8 + scoreNumericText(child.Text) * 0.2
            end
        end

        for key, value in pairs(item:GetAttributes()) do
            if type(value) == "string" then
                score += scoreRarityText(value)
            elseif type(value) == "number" then
                score += math.clamp(value, 0, 3000)
            end
        end

        score += math.max(0, 120 - math.floor(item.AbsoluteSize.Y / 10))
    end

    local module = getSwordModule()
    if module and candidate.name and candidate.name ~= "" then
        local ok, data = pcall(module.GetSword, module, candidate.name)
        if ok and type(data) == "table" then
            score += scoreRarityText(data.Rarity or data.Tier or data.Quality)
            score += tonumber(data.Rarity or data.Value or data.Price or data.Order) or 0
        end
    end

    return score + (tonumber(candidate.layoutOrder) or 0) * 0.01
end

getgenv().autoEquipBestSword = function()
    local candidates = getSwordCardCandidates()
    local bestName, bestScore

    for _, candidate in ipairs(candidates) do
        local title = candidate.item and candidate.item:FindFirstChild("Title", true)
            or candidate.item and candidate.item:FindFirstChild("ItemName", true)
        if title and title:IsA("TextLabel") and title.Text ~= "" then
            candidate.name = title.Text
        end

        candidate.layoutOrder = candidate.item and candidate.item.LayoutOrder or 0
        candidate.score = scoreSwordCandidate(candidate)

        if candidate.name and candidate.name ~= "" and candidate.name ~= "Default"
            and (not bestScore or candidate.score > bestScore) then
            bestName, bestScore = candidate.name, candidate.score
        end
    end

    if not bestName then
        return false
    end

    if not bestName or bestName == getgenv().AutoBestSwordEquipped then
        return bestName ~= nil, bestName
    end

    getgenv().skinChanger = true
    getgenv().swordModel = bestName
    getgenv().swordAnimations = bestName
    getgenv().swordFX = bestName
    getgenv().AutoBestSwordEquipped = bestName

    if getgenv().updateSword then
        task.spawn(getgenv().updateSword)
    end

    task.delay(0.18, function()
        pcall(function()
            local remotes = ReplicatedStorage:FindFirstChild("Remotes")
            if remotes and remotes:FindFirstChild("FireSwordInfo") then
                remotes.FireSwordInfo:FireServer(bestName)
            end
        end)
    end)

    return true, bestName
end

getgenv().setAutoEquipBestSword = function(enabled)
    if SkinChanger.autoEquipLoop then
        task.cancel(SkinChanger.autoEquipLoop)
        SkinChanger.autoEquipLoop = nil
    end

    if SkinChanger.autoEquipRespawn then
        SkinChanger.autoEquipRespawn:Disconnect()
        SkinChanger.autoEquipRespawn = nil
    end

    if not enabled then
        getgenv().AutoBestSwordEquipped = nil
        return
    end

    SkinChanger.autoEquipLoop = task.spawn(function()
        local attempts = 0
        while attempts < 80 and getgenv().AutoEquipBestEnabled do
            attempts += 1
            local ok, name = getgenv().autoEquipBestSword()
            if ok and name then
                break
            end
            task.wait(0.35)
        end
    end)

    SkinChanger.autoEquipRespawn = LocalPlayer.CharacterAdded:Connect(function(character)
        if not getgenv().AutoEquipBestEnabled then return end
        character:WaitForChild("Humanoid", 5)
        task.wait(0.55)
        task.spawn(getgenv().autoEquipBestSword)
    end)

    if LocalPlayer.Character then
        task.spawn(getgenv().autoEquipBestSword)
    end
end

