                    getgenv().ResetterConnection = nil
                end

                local char = localPlayer.Character
                if char then
                    local hrp = char:FindFirstChild('HumanoidRootPart')
                    local humanoid = char:FindFirstChild('Humanoid')
                    if (1<2) and (humanoid) then
